import{_ as a}from"./chunks/pixhack_v3_157_large_default.BboimA-g.js";import{_ as l,c as r,j as i,a as o,G as s,al as n,B as d,o as c}from"./chunks/framework.ByhWQ_D0.js";const P=JSON.parse('{"title":"CUAV Pixhack V3 (Discontinued)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_controller/pixhack_v3.md","filePath":"zh/flight_controller/pixhack_v3.md"}'),h={name:"zh/flight_controller/pixhack_v3.md"};function p(u,t,m,f,b,k){const e=d("Badge");return c(),r("div",null,[t[0]||(t[0]=i("h1",{id:"cuav-pixhack-v3-discontinued",tabindex:"-1"},[o("CUAV Pixhack V3 (Discontinued) "),i("a",{class:"header-anchor",href:"#cuav-pixhack-v3-discontinued","aria-label":'Permalink to "CUAV Pixhack V3 (Discontinued)"'},"​")],-1)),s(e,{type:"info",text:"Discontinued"}),t[1]||(t[1]=n('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This flight controller has been <a href="./../flight_controller/autopilot_experimental.html">discontinued</a> and is no longer commercially available.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The CUAV <em>Pixhack V3</em> flight controller board is a flexible autopilot intended primarily for manufacturers of commercial systems.</p><p>The board is a variant of the SOLO Pixhawk<sup>®</sup> 2 (PH2) flight controller, which is in turn based on the <a href="https://pixhawk.org/" target="_blank" rel="noreferrer">Pixhawk-project</a> <strong>FMUv3</strong> open hardware design. It runs PX4 on the <a href="https://nuttx.apache.org/" target="_blank" rel="noreferrer">NuttX</a> OS, and is fully compatible with both PX4 or ArduPilot<sup>®</sup> (APM) firmware.</p><p><em>Pixhack V3</em> has significant improvements with respect to the original design, including better interface layout and the addition of vibration damping and a thermostat system.</p><p><img src="'+a+'" alt="Pixhack v3"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported.html">manufacturer supported</a>.</p></div><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><ul><li>微处理器： <ul><li>STM32F427</li><li>STM32F100 (故障保护协处理器)</li></ul></li><li>传感器： <ul><li>加速度计 (3): LSM303D,MPU6000,MPU6000</li><li>陀螺仪 (3): L3GD20, MPU6000, MPU9250</li><li>指南针 (2): LS303D, MPU9250</li><li>气压计 (2): MS5611*2</li></ul></li><li>接口： <ul><li>MAVLink UART (2)</li><li>GPS UART (2)</li><li>DEBUG UART (1)</li><li>遥控信号输入(支持PPM, SBUS, DSM/DSM2)</li><li>RSSI输入: PWM或3.3ADC</li><li>I2C总线 (2)</li><li>CAN总线 (1)</li><li>ADC输入: 3.3V X1 , 6.6V X1</li><li>PWM输出: 8 PWM IO + 4 IO</li></ul></li><li>电源系统 <ul><li>Power口输入电压: 4.5 ~ 5.5 V</li><li>USB口输入电压：5.0 V +- 0.25v</li></ul></li><li>重量和尺寸: <ul><li>重量: 63g</li><li>宽度：68mm</li><li>厚度: 17mm</li><li>长度：44mm</li></ul></li><li>其它特性: <ul><li>工作温度: -20 ~ 60°C</li></ul></li></ul><h2 id="访问链接" tabindex="-1">访问链接 <a class="header-anchor" href="#访问链接" aria-label="Permalink to &quot;访问链接&quot;">​</a></h2><p>The board can be purchased from:</p><ul><li><a href="https://leixun.aliexpress.com/store" target="_blank" rel="noreferrer">leixun.aliexpress.com/store</a></li></ul><h2 id="编译固件" tabindex="-1">编译固件 <a class="header-anchor" href="#编译固件" aria-label="Permalink to &quot;编译固件&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware! It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4.html">build PX4</a> for this target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v3_default</span></span></code></pre></div><h2 id="串口映射" tabindex="-1">串口映射 <a class="header-anchor" href="#串口映射" aria-label="Permalink to &quot;串口映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>设备</th><th>Port</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>IO debug</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (flow control)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (flow control)</td></tr><tr><td>UART4</td><td></td><td></td></tr><tr><td>UART7</td><td></td><td>CONSOLE</td></tr><tr><td>UART8</td><td></td><td>SERIAL4</td></tr></tbody></table>',18))])}const v=l(h,[["render",p]]);export{P as __pageData,v as default};
